-- Generated additive Directory input row-lock custody correction.
-- The packaged operator must validate TLS/target and lock/check the exact applied
-- migration ledger in this same transaction before invoking this metadata owner.
DO $native_people_directory_row_lock_custody$
DECLARE phase text; observed text; rights_valid boolean;
 expected_prior text; expected_final text;
 relation_name text; locked_relations integer:=0;
BEGIN
 IF session_user<>current_user OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=session_user AND rolsuper)
  OR session_user IN ('console_app','console_rt','console_auth_rt','console_auth_startup',
   'console_leave_cmd','console_leave_definer','console_ontology_cmd','console_ontology_writer',
   'console_platform_force_cmd','console_account_owner','console_terms_owner','console_credential_owner',
   'console_durability_observer') THEN RAISE EXCEPTION 'native_people_directory.operator_identity_mismatch'; END IF;
 IF pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'native_people_directory.unsupported_isolation'; END IF;
 PERFORM pg_catalog.set_config('search_path','pg_catalog,pg_temp',true);
 PERFORM pg_catalog.set_config('lock_timeout','1s',true);
 FOR relation_name IN SELECT c.relname::text FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relkind IN ('r','p') AND c.relname IN ('account_context_candidates','account_security','account_security_events','account_terms_acceptances','account_terms_head','account_terms_release_receipts','accounts','audit_events','auth_bootstrap_credentials','auth_device_login_handoffs','auth_refresh_token_families','auth_refresh_tokens','auth_webauthn_ceremonies','auth_webauthn_ceremony_bindings','auth_webauthn_credentials','cedar_policy_catalog_entries','company_actors','company_authority_heads','company_enrollment_effect_bindings','company_enrollment_receipts','company_enrollment_request_events','company_enrollment_requests','deployment_operator_head','deployment_operator_receipts','employee_employment_profiles','employee_lifecycle_events','employee_person_bindings','employees','employment_revisions','employment_source_bindings','group_authority_heads','group_membership_revisions','group_memberships','group_role_grants','groups','leave_balance_import_receipts','native_company_action_refs','native_company_catalog_installs','native_company_object_refs','native_company_policy_inputs_v1','native_company_policy_receipts_v1','native_company_property_refs','native_people_inputs_v1','native_people_terminals_v1','ont_action_command_receipts','ont_action_types','ont_analytics','ont_builtin_catalog_allowlist','ont_builtin_catalog_installs','ont_link_types','ont_object_policies','ont_object_type_key_revisions','ont_object_types','ont_property_defs','organizations','person_revisions','persons','platform_force_removal_effect_bindings','platform_force_removal_receipts','platform_legacy_catalog_effect_bindings','platform_legacy_membership_effect_bindings','platform_legacy_topology_effect_bindings','platform_legacy_topology_receipts','platform_legacy_user_birth_witnesses','policy_assignment_revisions','policy_capability_clause_fields','policy_capability_clauses','policy_role_conditions','policy_role_permissions','policy_role_revisions','policy_roles','user_role_assignments','users') ORDER BY c.relname COLLATE "C"
 LOOP
  EXECUTE pg_catalog.format('LOCK TABLE ONLY public.%I IN ACCESS EXCLUSIVE MODE',relation_name);
  locked_relations:=locked_relations+1;
 END LOOP;
 IF locked_relations<>73 THEN RAISE EXCEPTION 'native_people_directory.profile_mismatch'; END IF;
 SELECT classified.state,captured.snapshot_sha256,captured.native_directory_startup_rights_valid
 INTO phase,observed,rights_valid FROM (
WITH full_capture AS (
